package com.cdac.cssip.meeting.config;import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;@RestControllerAdvice public class ApiExceptionHandler{@ExceptionHandler(MethodArgumentNotValidException.class)ResponseEntity<?>v(MethodArgumentNotValidException e){String m=e.getBindingResult().getFieldErrors().stream().map(x->x.getDefaultMessage()).findFirst().orElse("Validation failed");return body(HttpStatus.BAD_REQUEST,m);}@ExceptionHandler(Exception.class)ResponseEntity<?>e(Exception e){HttpStatus s=e instanceof NoSuchElementException?HttpStatus.NOT_FOUND:e instanceof SecurityException?HttpStatus.FORBIDDEN:e instanceof IllegalStateException?HttpStatus.CONFLICT:HttpStatus.BAD_REQUEST;return body(s,e.getMessage()==null?e.getClass().getSimpleName():e.getMessage());}private ResponseEntity<?> body(HttpStatus s,String m){return ResponseEntity.status(s).body(Map.of("timestamp",Instant.now().toString(),"status",s.value(),"error",m));}}
